  `source_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '입력 방식: EXCEL 또는 MANUAL',
  `imported_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'DB 반영 입력 일시',
  `raw_data` longtext COLLATE utf8mb4_unicode_ci COMMENT '시트명·셀 주소별 원본값; 직접 입력은 NULL 허용',
