-- 테이블 equipment_group · 14행
CREATE TABLE `equipment_group` (
  `group_id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '설비군·모델 ID',
  `group_name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '표기를 통일한 설비군·모델명',
  `category` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '최상위 분류: POLY/OXIDE/KCTC/HPA',
  `parent_group_id` int(10) unsigned DEFAULT NULL COMMENT '기본 모델 ID; 기본형은 NULL',
  `analysis_enabled` tinyint(1) NOT NULL DEFAULT '1' COMMENT '공통 분석 포함 여부; HPA는 FALSE',
  PRIMARY KEY (`group_id`),
  KEY `ix_equipment_group_parent` (`parent_group_id`),
  KEY `ix_equipment_group_category` (`category`),
  CONSTRAINT `fk_equipment_group_parent` FOREIGN KEY (`parent_group_id`) REFERENCES `equipment_group` (`group_id`)
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='설비군·모델 및 원형·파생형 관계';

-- 테이블 equipment · 53행
CREATE TABLE `equipment` (
  `equipment_id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '실제 호기 ID; 개조 전후에도 유지',
  `equipment_code` varbinary(200) NOT NULL COMMENT '설비호기 코드; 모든 사업장에서 고유, 사업장별 중복 생성 금지',
  PRIMARY KEY (`equipment_id`),
  UNIQUE KEY `uq_equipment_code` (`equipment_code`)
) ENGINE=InnoDB AUTO_INCREMENT=54 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='실제 설비; 호기 코드는 전체 사업장에서 고유';

-- 테이블 version_family · 15행
CREATE TABLE `version_family` (
  `family_id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '버전 계열 ID',
  `group_id` int(10) unsigned NOT NULL COMMENT '계열 관리 모델 ID; 실제 적용 모델 전체 목록을 뜻하지 않음',
  `family_name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '버전 계열명; C3 구UI·통합UI 분리, 같은 UI 안에서는 형상 무관 공유',
  `ui_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'UI 유형: LEGACY/INTEGRATED/SMART; 미확인은 NULL',
  PRIMARY KEY (`family_id`),
  KEY `ix_version_family_group` (`group_id`),
  CONSTRAINT `fk_version_family_group` FOREIGN KEY (`group_id`) REFERENCES `equipment_group` (`group_id`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='버전 계열; 기준 N은 조회 조건으로 전달';

-- 테이블 release_note · 7행
CREATE TABLE `release_note` (
  `release_note_id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '릴리즈 노트 ID',
