  KEY `ix_release_note_batch` (`batch_id`),
  CONSTRAINT `fk_release_note_batch` FOREIGN KEY (`batch_id`) REFERENCES `import_batch` (`batch_id`),
  CONSTRAINT `fk_release_note_group` FOREIGN KEY (`group_id`) REFERENCES `equipment_group` (`group_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='릴리즈 노트 문서';

-- 테이블 release_version · 69행
CREATE TABLE `release_version` (
  `release_version_id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '릴리즈 버전 ID',
  `release_note_id` int(10) unsigned DEFAULT NULL COMMENT '릴리즈 노트 ID; 문서 없이 직접 등록하면 NULL',
  `family_id` int(10) unsigned NOT NULL COMMENT '버전 계열 ID',
  `version_raw` varbinary(400) NOT NULL COMMENT '릴리즈 SW 버전 원문; 핫픽스 표기 포함',
  `version_suffix` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '파생 접미사: _DFB=DFB, _DEX=Plus 등',
  `released_at` date DEFAULT NULL COMMENT 'SW 버전 출시일; 미확인은 NULL',
  `version_order` int(11) DEFAULT NULL COMMENT '같은 계열의 확인된 비교 순서; 미확인은 NULL, 원본 No 차이와 구분',
  `item_mapping_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT 'UNKNOWN' COMMENT '항목 매핑 확인 상태: UNKNOWN/VERIFIED',
  `batch_id` int(10) unsigned NOT NULL COMMENT '이 릴리즈 버전 정보의 입력 작업 ID',
  `source_reference` longtext COLLATE utf8mb4_unicode_ci COMMENT '필드별 원본 시트명·셀 주소; No 등 정렬 근거 포함',
  `edited_fields` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '사용자가 직접 수정한 필드명 목록',
  PRIMARY KEY (`release_version_id`),
  UNIQUE KEY `uq_release_version_family_raw` (`family_id`,`version_raw`),
  KEY `ix_release_version_note` (`release_note_id`),
  KEY `ix_release_version_order` (`family_id`,`version_order`),
  KEY `ix_release_version_batch` (`batch_id`),
  CONSTRAINT `fk_release_version_batch` FOREIGN KEY (`batch_id`) REFERENCES `import_batch` (`batch_id`),
  CONSTRAINT `fk_release_version_family` FOREIGN KEY (`family_id`) REFERENCES `version_family` (`family_id`),
  CONSTRAINT `fk_release_version_note` FOREIGN KEY (`release_note_id`) REFERENCES `release_note` (`release_note_id`)
) ENGINE=InnoDB AUTO_INCREMENT=70 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='릴리즈 SW 버전 및 계열별 확인된 순서';

-- 테이블 item · 165행
CREATE TABLE `item` (
  `item_id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '변경 항목 ID',
  `release_note_id` int(10) unsigned DEFAULT NULL COMMENT '릴리즈 노트 ID; 원본에 없는 수동 Item은 NULL 허용',
