  `batch_id` int(10) unsigned NOT NULL COMMENT '이 Item 정보의 입력 작업 ID',
  `source_reference` longtext COLLATE utf8mb4_unicode_ci COMMENT '필드별 원본 시트명·셀 주소; 직접 입력은 NULL 허용',
  `edited_fields` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '사용자가 직접 수정한 필드명 목록',
  `jira_code` varchar(200) DEFAULT NULL COMMENT 'Item Jira 코드; 미기재는 NULL',
  PRIMARY KEY (`item_id`),
