  KEY `ix_item_batch` (`batch_id`),
  CONSTRAINT `fk_item_batch` FOREIGN KEY (`batch_id`) REFERENCES `import_batch` (`batch_id`),
  CONSTRAINT `fk_item_note` FOREIGN KEY (`release_note_id`) REFERENCES `release_note` (`release_note_id`)
) ENGINE=InnoDB AUTO_INCREMENT=166 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='릴리즈 노트의 변경 항목';

-- 테이블 equipment_snapshot · 159행
CREATE TABLE `equipment_snapshot` (
  `snapshot_id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '기준일별 설비 현황 ID',
  `equipment_id` int(10) unsigned NOT NULL COMMENT '실제 호기 ID',
  `base_date` date NOT NULL COMMENT 'Excel 현황 기준일; 입력 일시와 구분',
  `site` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '해당 기준일의 사업장',
  `line` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '해당 기준일의 라인; 필수 여부는 자료 검증 규칙에 따름',
  `model_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '원본 설비 모델명; 혼합형 표기 보존',
  `group_id` int(10) unsigned DEFAULT NULL COMMENT '확인된 대표 모델 ID; 혼합형은 NULL 허용',
  `production_area` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '선택 속성 MEMORY/FOUNDRY; NULL은 미확인, 모델 소속 제한 금지',
  `structure_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'INLINE/CLUSTER 등 장비 구조',
  `geometry_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '5각/6각 등 형상 원문; C3는 같은 UI 안에서 형상과 무관하게 릴리즈·계열 공유',
  `modification_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'CIP 등 개조 유형; 없으면 NULL',
  `batch_id` int(10) unsigned NOT NULL COMMENT '이 현황 정보의 입력 작업 ID',
  `source_reference` longtext COLLATE utf8mb4_unicode_ci COMMENT '필드별 원본 시트명·셀 주소',
  PRIMARY KEY (`snapshot_id`),
  UNIQUE KEY `uq_equipment_snapshot_date` (`equipment_id`,`base_date`),
  KEY `ix_equipment_snapshot_date_site_line` (`base_date`,`site`,`line`),
  KEY `ix_equipment_snapshot_group_date` (`group_id`,`base_date`),
  KEY `ix_equipment_snapshot_batch` (`batch_id`),
  CONSTRAINT `fk_equipment_snapshot_batch` FOREIGN KEY (`batch_id`) REFERENCES `import_batch` (`batch_id`),
  CONSTRAINT `fk_equipment_snapshot_equipment` FOREIGN KEY (`equipment_id`) REFERENCES `equipment` (`equipment_id`),
  CONSTRAINT `fk_equipment_snapshot_group` FOREIGN KEY (`group_id`) REFERENCES `equipment_group` (`group_id`)
) ENGINE=InnoDB AUTO_INCREMENT=160 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='기준일별 설비 소속·모델·개조 상태';

-- 테이블 equipment_version · 159행
CREATE TABLE `equipment_version` (
  `equipment_version_id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '설비 적용 버전 이력 ID',
  `snapshot_id` int(10) unsigned NOT NULL COMMENT '기준일별 설비 현황 ID',
  `family_id` int(10) unsigned NOT NULL COMMENT '적용 버전 계열 ID; 미등록 버전도 보존',
  `version_raw` varbinary(400) NOT NULL COMMENT '실제 적용 SW 버전 원문; 같은 계열 PM의 드문 차이도 보존',
  `release_version_id` int(10) unsigned DEFAULT NULL COMMENT '확인된 릴리즈 버전 ID; 미등록·삭제 시 NULL',
  `batch_id` int(10) unsigned NOT NULL COMMENT '이 적용 버전 정보의 입력 작업 ID',
  `source_reference` longtext COLLATE utf8mb4_unicode_ci COMMENT '필드별 원본 시트명·셀 주소',
  PRIMARY KEY (`equipment_version_id`),
  UNIQUE KEY `uq_equipment_version_snapshot_id` (`snapshot_id`,`equipment_version_id`),
  UNIQUE KEY `uq_equipment_version_snapshot_family_raw` (`snapshot_id`,`family_id`,`version_raw`),
  KEY `ix_equipment_version_family_raw` (`family_id`,`version_raw`),
  KEY `ix_equipment_version_release` (`release_version_id`),
  KEY `ix_equipment_version_batch` (`batch_id`),
  CONSTRAINT `fk_equipment_version_batch` FOREIGN KEY (`batch_id`) REFERENCES `import_batch` (`batch_id`),
  CONSTRAINT `fk_equipment_version_family` FOREIGN KEY (`family_id`) REFERENCES `version_family` (`family_id`),
  CONSTRAINT `fk_equipment_version_release` FOREIGN KEY (`release_version_id`) REFERENCES `release_version` (`release_version_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_equipment_version_snapshot` FOREIGN KEY (`snapshot_id`) REFERENCES `equipment_snapshot` (`snapshot_id`)
) ENGINE=InnoDB AUTO_INCREMENT=160 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='설비 적용 SW 버전 이력; 여러 PM이 공유 가능';

-- 테이블 equipment_pm · 0행
CREATE TABLE `equipment_pm` (
