  `batch_id` int(10) unsigned NOT NULL COMMENT '이 PM 정보의 입력 작업 ID',
  `source_reference` longtext COLLATE utf8mb4_unicode_ci COMMENT '필드별 원본 시트명·셀 주소',
  PRIMARY KEY (`pm_id`),
  UNIQUE KEY `uq_equipment_pm_name` (`snapshot_id`,`pm_name`),
  KEY `ix_equipment_pm_snapshot_version` (`snapshot_id`,`equipment_version_id`),
  KEY `ix_equipment_pm_group` (`group_id`),
  KEY `ix_equipment_pm_batch` (`batch_id`),
  CONSTRAINT `fk_equipment_pm_batch` FOREIGN KEY (`batch_id`) REFERENCES `import_batch` (`batch_id`),
  CONSTRAINT `fk_equipment_pm_group` FOREIGN KEY (`group_id`) REFERENCES `equipment_group` (`group_id`),
  CONSTRAINT `fk_equipment_pm_snapshot` FOREIGN KEY (`snapshot_id`) REFERENCES `equipment_snapshot` (`snapshot_id`),
  CONSTRAINT `fk_equipment_pm_snapshot_version` FOREIGN KEY (`snapshot_id`, `equipment_version_id`) REFERENCES `equipment_version` (`snapshot_id`, `equipment_version_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='기준일별 PM 구성과 적용 버전 연결';

-- 테이블 release_version_item · 165행
CREATE TABLE `release_version_item` (
