  `target_reference` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '계열·Item 번호·버전 원문 등 삭제 후 재연결에 사용할 근거',
  `mapping_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT 'UNRESOLVED' COMMENT '연결 확인 상태: VERIFIED/UNRESOLVED',
  PRIMARY KEY (`risk_rule_id`),
  KEY `ix_risk_rule_family_status` (`family_id`,`mapping_status`),
