  CONSTRAINT `fk_risk_rule_end_version` FOREIGN KEY (`end_release_version_id`) REFERENCES `release_version` (`release_version_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_risk_rule_family` FOREIGN KEY (`family_id`) REFERENCES `version_family` (`family_id`),
  CONSTRAINT `fk_risk_rule_group` FOREIGN KEY (`group_id`) REFERENCES `equipment_group` (`group_id`),
  CONSTRAINT `fk_risk_rule_item` FOREIGN KEY (`item_id`) REFERENCES `item` (`item_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_risk_rule_start_version` FOREIGN KEY (`start_release_version_id`) REFERENCES `release_version` (`release_version_id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='환경안전·결함 위험의 수동 지정과 재연결 근거';

-- 테이블 app_setting · 13행
CREATE TABLE `app_setting` (
  `setting_key` varbinary(400) NOT NULL COMMENT '설정 이름',
  `setting_value` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '설정값; 노후도 주의·위험 기간과 단위 등',
  PRIMARY KEY (`setting_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='관리 설정; 사용자 인증·권한 테이블과 구분';

